      stateManager.setPointerCoordinates({
        screenX: Math.round(pointer.x),
        screenY: Math.round(pointer.y),
        imageX: norm.imageX,
        imageY: norm.imageY,
        normalizedX: norm.x,
        normalizedY: norm.y,
        isInsideMap: norm.isInside
      });
